// Works out the look-back window. Scan Registrations then pages through every upcoming,
// active registration changed inside it, so a missed run is caught by the next one.
const cfg_obj = $('Config').first().json;
const since_str = $now.minus({ minutes: Number(cfg_obj.LOOKBACK_MINUTES) || 180 }).toUTC().toFormat("yyyy-MM-dd'T'HH:mm:ss'Z'");
const query_str = 'query ScanRegistrations($today: String!, $since: String!, $first: Int, $after: String) { learners(first: $first, after: $after, filters: [' +
  '{ field: isActive, operation: eq, value: "true" }, ' +
  '{ field: eventStartDate, operation: ge, value: $today }, ' +
  '{ field: lastUpdatedAt, operation: ge, value: $since }' +
  ']) { pageInfo { hasNextPage endCursor } edges { node { id notes contact { id emailAddress personalName { firstName lastName } } event { id } customFieldValues { definitionKey value } } } } }';
return [{ json: { scanQuery: query_str, today: $now.toISODate(), since: since_str, pageSize: Number(cfg_obj.SCAN_PAGE_SIZE) || 100 } }];

// Keeps only the registrations flagged for substitution: one item per request.
// Scan Registrations returns one item per page of results.
const cfg_obj = $('Config').first().json;
const pages_ary = $input.all();
const out_ary = [];
const seen_obj = {};
for (const page_obj of pages_ary) {
  const res_obj = page_obj.json || {};
  if (res_obj.errors || !res_obj.data || !res_obj.data.learners) {
    throw new Error('Scan query failed: ' + JSON.stringify(res_obj.errors || res_obj).slice(0, 500));
  }
  for (const edge_obj of (res_obj.data.learners.edges || [])) {
    const l_obj = edge_obj.node || {};
    if (!l_obj.id || seen_obj[l_obj.id]) { continue; }
    seen_obj[l_obj.id] = true;
    const cf_obj = {};
    for (const v_obj of (l_obj.customFieldValues || [])) { cf_obj[v_obj.definitionKey] = v_obj.value; }
    if (cf_obj[cfg_obj.CHANGE_TYPE_FIELD_KEY] !== cfg_obj.VALUE_REQUESTED) { continue; }
    const contact_obj = l_obj.contact || {};
    const name_obj = contact_obj.personalName || {};
    out_ary.push({ json: {
      learnerId: l_obj.id,
      learnerNotes: l_obj.notes || '',
      eventId: (l_obj.event || {}).id || '',
      outgoingContactId: contact_obj.id || '',
      outgoingEmail: contact_obj.emailAddress || '',
      outgoingName: ((name_obj.firstName || '') + ' ' + (name_obj.lastName || '')).trim(),
      replacementEmail: String(cf_obj[cfg_obj.SUBSTITUTE_EMAIL_FIELD_KEY] || '').trim().toLowerCase()
    } });
  }
}
// A partial scan must not pass for a complete one: stop and say so.
const last_obj = (pages_ary[pages_ary.length - 1] || {}).json || {};
if ((((last_obj.data || {}).learners || {}).pageInfo || {}).hasNextPage) {
  throw new Error('Scan stopped at the page limit before reading every changed registration. Shorten LOOKBACK_MINUTES or raise SCAN_PAGE_SIZE (100 at most), then run again.');
}
return out_ary;

// Checks the request against live data and prepares the writes. Nothing is written here.
// Existing registrations and capacity are checked next, in Confirm Not Registered.
const req_obj = $('Loop Over Requests').item.json;
const res_obj = $json || {};
const stamp_str = $now.toUTC().toFormat('yyyy-MM-dd HH:mm') + ' UTC';
const base_obj = Object.assign({}, req_obj, { stamp: stamp_str });
const refuse_fn = function (reason_str) { return { json: Object.assign(base_obj, { action: 'refuse', reason: reason_str }) }; };
if (res_obj.errors || !res_obj.data) { return { json: Object.assign(base_obj, { action: 'skip', reason: 'Read failed, will retry on the next run: ' + JSON.stringify(res_obj.errors || res_obj).slice(0, 300) }) }; }
if (!req_obj.replacementEmail) { return refuse_fn('No substitute email was entered.'); }
const contacts_ary = (((res_obj.data.contacts || {}).edges) || []).map(function (e_obj) { return e_obj.node; });
const event_obj = ((((res_obj.data.events || {}).edges) || [])[0] || {}).node;
if (!event_obj) { return refuse_fn('The event could not be read.'); }
if (contacts_ary.length === 0) { return refuse_fn('No contact found with the email ' + req_obj.replacementEmail + '.'); }
if (contacts_ary.length > 1) { return refuse_fn('Several contacts share the email ' + req_obj.replacementEmail + '.'); }
const in_obj = contacts_ary[0];
if (in_obj.id === req_obj.outgoingContactId) { return refuse_fn('The substitute is the same person as the learner giving up the place.'); }
const inName_str = (((in_obj.personalName || {}).firstName || '') + ' ' + ((in_obj.personalName || {}).lastName || '')).trim();
const line_str = '[Substitution ' + stamp_str + '] ' + req_obj.outgoingName + ' released the place and ' + inName_str + ' was registered instead. This is a substitution, not a withdrawal.';
return { json: Object.assign(base_obj, {
  action: 'substitute',
  incomingContactId: in_obj.id,
  incomingEmail: in_obj.emailAddress || '',
  incomingName: inName_str,
  incomingFirstName: (in_obj.personalName || {}).firstName || inName_str,
  eventCode: event_obj.code || '',
  eventTitle: event_obj.title || '',
  eventStart: String(event_obj.start || '').slice(0, 16).replace('T', ' '),
  eventLocation: (event_obj.location || {}).name || '',
  eventRemainingPlaces: event_obj.remainingPlaces,
  auditLine: line_str
}) };

// Looks at any active registration the substitute already has on the event.
// One created by an earlier, interrupted run for this same request is resumed;
// any other one is refused. Capacity is only checked for a fresh substitution.
const cfg_obj = $('Config').first().json;
const dec_obj = $('Decide').item.json;
if (dec_obj.action !== 'substitute') { return { json: dec_obj }; }
const res_obj = $json || {};
if (res_obj.errors || !res_obj.data || !res_obj.data.learners) {
  return { json: Object.assign({}, dec_obj, { action: 'skip', reason: 'Registration check failed, will retry on the next run: ' + JSON.stringify(res_obj.errors || res_obj).slice(0, 300) }) };
}
const found_ary = (res_obj.data.learners.edges || []).map(function (e_obj) { return e_obj.node; });
if (found_ary.length > 0) {
  const cf_obj = {};
  for (const v_obj of (found_ary[0].customFieldValues || [])) { cf_obj[v_obj.definitionKey] = v_obj.value; }
  const sameRequest_bool = cf_obj[cfg_obj.CHANGE_TYPE_FIELD_KEY] === cfg_obj.VALUE_TAKEN_OVER &&
    String(cf_obj[cfg_obj.SUBSTITUTE_EMAIL_FIELD_KEY] || '').trim().toLowerCase() === String(dec_obj.outgoingEmail || '').trim().toLowerCase();
  if (sameRequest_bool) {
    return { json: Object.assign({}, dec_obj, { action: 'resume', incomingLearnerId: found_ary[0].id, reason: 'The substitute was registered by an earlier run; finishing the release.' }) };
  }
  return { json: Object.assign({}, dec_obj, { action: 'refuse', reason: dec_obj.incomingName + ' is already registered on this event.' }) };
}
const places_any = dec_obj.eventRemainingPlaces;
if (places_any !== null && places_any !== undefined && Number(places_any) <= 0) {
  return { json: Object.assign({}, dec_obj, { action: 'refuse', reason: 'The event is full. The substitute is registered before the place is released, so a full event needs one place freed by an administrator first.' }) };
}
return { json: dec_obj };

// registerNamedLearners returns a list of results, one per learner in the input.
// A domain error (Administrate refused) becomes a refusal; anything unexpected stops the run,
// and the request is picked up again on the next run.
const dec_obj = $('Confirm Not Registered').item.json;
const res_obj = $json || {};
const raw_any = ((res_obj.data || {}).event || {}).registerNamedLearners;
if (res_obj.errors || raw_any === undefined || raw_any === null) {
  throw new Error('No usable response from Administrate when registering ' + dec_obj.incomingName + ' on event ' + dec_obj.eventId + ': ' + JSON.stringify(res_obj.errors || res_obj).slice(0, 300));
}
const results_ary = Array.isArray(raw_any) ? raw_any : [raw_any];
let errs_ary = [];
let learners_ary = [];
for (const r_obj of results_ary) {
  errs_ary = errs_ary.concat((r_obj && r_obj.errors) || []);
  learners_ary = learners_ary.concat((r_obj && r_obj.learners) || []);
}
const ok_bool = errs_ary.length === 0 && learners_ary.length > 0;
return { json: Object.assign({}, dec_obj, {
  registered: ok_bool,
  incomingLearnerId: ok_bool ? learners_ary[0].id : '',
  reason: ok_bool ? '' : 'Administrate refused to register the substitute: ' + (errs_ary.map(function (e_obj) { return e_obj.message; }).join('; ') || 'no learner was returned')
}) };

// The substitute is registered at this point. Every expected result must be present
// and clean; otherwise stop with the details so an administrator can finish by hand.
const dec_obj = $('Confirm Not Registered').item.json;
const res_obj = $json || {};
const d_obj = res_obj.data || {};
const tag_obj = (d_obj.tag || {}).update;
const cancel_obj = (d_obj.cancel || {}).cancel;
const errs_ary = (res_obj.errors || []).concat((tag_obj && tag_obj.errors) || []).concat((cancel_obj && cancel_obj.errors) || []);
if (!tag_obj || !cancel_obj || errs_ary.length > 0) {
  throw new Error('Substitute ' + dec_obj.incomingName + ' is registered on event ' + dec_obj.eventId + ' but releasing the place of ' + dec_obj.outgoingName + ' (learner ' + dec_obj.learnerId + ') did not complete: ' + (errs_ary.map(function (e_obj) { return e_obj.message; }).join('; ') || 'missing response') + '. Finish it by hand.');
}
return { json: dec_obj };

// Written only after the release is verified, so a success entry is always true.
const dec_obj = $('Check Release').item.json;
const res_obj = $json || {};
const log_obj = ((res_obj.data || {}).externalLog || {}).createExternalIntegrationLog;
const errs_ary = (res_obj.errors || []).concat((log_obj && log_obj.errors) || []);
if (!log_obj || errs_ary.length > 0) {
  throw new Error('Substitution for ' + dec_obj.outgoingName + ' on event ' + dec_obj.eventId + ' is complete, but the success log could not be written: ' + (errs_ary.map(function (e_obj) { return e_obj.message; }).join('; ') || 'missing response'));
}
return { json: dec_obj };

const cfg_obj = $('Config').first().json;
const d_obj = $json;
const esc_fn = function (v_any) { return String(v_any === null || v_any === undefined ? '' : v_any).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;').split('"').join('&quot;'); };
const row_fn = function (k_str, v_str) { return '<tr><td style="padding:8px 0;color:#5A6472;font-size:13px;width:160px;">' + esc_fn(k_str) + '</td><td style="padding:8px 0;color:#16202B;font-size:14px;">' + esc_fn(v_str) + '</td></tr>'; };
const html_str = '<div style="font-family:Arial,Helvetica,sans-serif;background:#F4F6F8;padding:24px;"><table width="600" cellpadding="0" cellspacing="0" style="background:#FFFFFF;border-radius:8px;"><tr><td style="background:' + esc_fn(cfg_obj.BRAND_COLOUR) + ';padding:18px 24px;color:#FFFFFF;font-size:18px;font-weight:bold;">' + esc_fn(cfg_obj.BRAND_NAME) + '</td></tr><tr><td style="padding:24px;"><p style="font-size:15px;color:#16202B;">Hello ' + esc_fn(d_obj.incomingFirstName) + ',</p><p style="font-size:15px;color:#16202B;">' + esc_fn(d_obj.outgoingName) + ' can no longer attend <strong>' + esc_fn(d_obj.eventTitle) + '</strong> and the place has been transferred to you. Your registration is confirmed.</p><table cellpadding="0" cellspacing="0" style="margin:16px 0;">' + row_fn('Event', d_obj.eventCode) + row_fn('Starts', d_obj.eventStart) + row_fn('Location', d_obj.eventLocation) + '</table><p style="font-size:13px;color:#5A6472;">If you cannot attend, please let us know as soon as possible so the place can be offered to someone else.</p></td></tr></table></div>';
return { json: Object.assign({}, d_obj, { emailBody: { query: 'mutation SendSubstitutionEmail($subject: String!, $body: String!) { contactAdhocEmails { sendContactAdhocEmail(input: { contactId: ' + JSON.stringify(d_obj.incomingContactId) + ', subject: $subject, body: $body, sendingAddressId: ' + JSON.stringify(cfg_obj.SENDING_ADDRESS_ID) + ' }) { errors { label message value } } } }', variables: { subject: 'A place has been transferred to you: ' + d_obj.eventTitle, body: html_str } } }) };

const dec_obj = $('Build Email').item.json;
const res_obj = $json || {};
const send_obj = ((res_obj.data || {}).contactAdhocEmails || {}).sendContactAdhocEmail;
const errs_ary = (res_obj.errors || []).concat((send_obj && send_obj.errors) || []);
if (!send_obj || errs_ary.length > 0) {
  throw new Error('Substitution for ' + dec_obj.outgoingName + ' is complete, but the confirmation email to ' + dec_obj.incomingName + ' was not sent: ' + (errs_ary.map(function (e_obj) { return e_obj.message; }).join('; ') || 'missing response'));
}
return { json: { learnerId: dec_obj.learnerId, outcome: 'substituted' } };

// Marks the request as refused on the registration, with the reason in its notes,
// so the administrator sees why and the next run does not try again.
const cfg_obj = $('Config').first().json;
const d_obj = $json;
const line_str = '[Substitution refused ' + d_obj.stamp + '] ' + d_obj.reason;
const notes_str = (d_obj.learnerNotes ? d_obj.learnerNotes + String.fromCharCode(10) : '') + line_str;
const logPart_str = d_obj.eventId ? ' log: externalLog { createExternalIntegrationLog(input: { originIdentifier: $origin, nodeId: ' + JSON.stringify(d_obj.eventId) + ', message: $message, status: failed }) { errors { label message value } } }' : '';
const query_str = 'mutation RefuseSubstitution($notes: String, $message: String!, $origin: String!) { tag: learner { update(input: { learnerId: ' + JSON.stringify(d_obj.learnerId) + ', notes: $notes, customFieldValues: [{ definitionKey: ' + JSON.stringify(cfg_obj.CHANGE_TYPE_FIELD_KEY) + ', value: ' + JSON.stringify(cfg_obj.VALUE_REFUSED) + ' }] }) { errors { label message value } } }' + logPart_str + ' }';
return { json: Object.assign({}, d_obj, { refuseBody: { query: query_str, variables: { notes: notes_str, message: 'Substitution refused for ' + d_obj.outgoingName + ': ' + d_obj.reason, origin: cfg_obj.ORIGIN_IDENTIFIER } } }) };

// If the refusal cannot be recorded, stop: otherwise the request would be retried
// on every run without anyone knowing why.
const dec_obj = $('Prepare Refusal').item.json;
const res_obj = $json || {};
const d_obj = res_obj.data || {};
const tag_obj = (d_obj.tag || {}).update;
const log_obj = dec_obj.eventId ? (d_obj.log || {}).createExternalIntegrationLog : { errors: [] };
const errs_ary = (res_obj.errors || []).concat((tag_obj && tag_obj.errors) || []).concat((log_obj && log_obj.errors) || []);
if (!tag_obj || !log_obj || errs_ary.length > 0) {
  throw new Error('Could not record the refused substitution for ' + dec_obj.outgoingName + ' (learner ' + dec_obj.learnerId + '): ' + (errs_ary.map(function (e_obj) { return e_obj.message; }).join('; ') || 'missing response') + '. Reason it was refused: ' + dec_obj.reason);
}
return { json: { learnerId: dec_obj.learnerId, outcome: 'refused' } };
